package in.otrail.extensions.mod1;

import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.net.Uri;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import in.otrail.AppStyle;import in.otrail.modules.ModuleV1;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;

/** Separate downloadable Debian shell module. */
public final class DebianShell implements ModuleV1 {
  private Activity activity;private Host host;private LinearLayout root;private TextView status,terminal,debug;private EditText command;private ScrollView terminalScroll;private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newCachedThreadPool();private java.lang.Process process;private OutputStream input;private boolean closed,launchAttempted;
  public String id(){return "mod3";}
  public View create(Activity a,Host h){activity=a;host=h;root=new LinearLayout(a);root.setOrientation(1);root.setPadding(dp(6),dp(4),dp(6),dp(4));root.setBackgroundColor(0xff10101b);
    LinearLayout session=row();session.addView(button("←",a::finish),new LinearLayout.LayoutParams(dp(52),dp(42)));TextView online=label("●",15);online.setTextColor(0xff01ff1f);session.addView(online);session.addView(label("Debian Shell · TERMINAL 1",18),new LinearLayout.LayoutParams(0,-2,1));session.addView(button("HALT SESSION",this::exit));root.addView(session);
    status=label("Preparing included Debian…",11);status.setMaxLines(3);root.addView(status);ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
    terminal=label("",12);terminal.setTypeface(Typeface.MONOSPACE);terminal.setTextIsSelectable(true);terminal.setBackgroundColor(Color.BLACK);terminalScroll=new ScrollView(a);terminalScroll.setFillViewport(true);terminalScroll.addView(terminal);root.addView(terminalScroll,new LinearLayout.LayoutParams(-1,0,1));
    LinearLayout entry=row();command=new EditText(a);command.setSingleLine(true);command.setHint("command · type exit to return");command.setTextColor(0xff40e0d0);command.setHintTextColor(0xffff7f50);entry.addView(command,new LinearLayout.LayoutParams(0,dp(46),1));entry.addView(button("SEND",()->send(command.getText().toString()+"\n")),new LinearLayout.LayoutParams(dp(68),dp(44)));root.addView(entry);command.setOnEditorActionListener((v,id,event)->{send(command.getText().toString()+"\n");return true;});
    LinearLayout keys=row();for(Button key:new Button[]{button("ESC",()->send("\u001b")),button("TAB",()->send("\t")),button("CTRL-C",()->send("\u0003")),button("←",()->send("\u001b[D")),button("↑",()->send("\u001b[A")),button("↓",()->send("\u001b[B")),button("→",()->send("\u001b[C"))})keys.addView(key,new LinearLayout.LayoutParams(0,dp(44),1));root.addView(keys);
    debug=label("DEBUG · ready",10);debug.setTextColor(0xff01ff1f);debug.setBackgroundColor(0xff050509);debug.setMaxLines(2);debug.setTextIsSelectable(true);root.addView(debug);LinearLayout modes=row();modes.addView(nav("▣ FILES",this::scpSync));modes.addView(nav("</> GOD",a::finish));modes.addView(nav(">_ START",this::startShell));modes.addView(nav("⚙ STORAGE",this::storage));modes.addView(nav("↻ REPAIR",()->{launchAttempted=false;setup();}));root.addView(modes);setup();handler.post(poll);return root;}
  private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}private LinearLayout row(){LinearLayout l=new LinearLayout(activity);l.setGravity(Gravity.CENTER_VERTICAL);return l;}private TextView label(String s,int size){TextView v=new TextView(activity);v.setText(s);v.setTextColor(0xff40e0d0);v.setTextSize(size);v.setPadding(dp(5),dp(4),dp(5),dp(4));return v;}private Button button(String s,Runnable r){Button b=new Button(activity);b.setText(s);AppStyle.button(b);b.setOnClickListener(v->{debug("RUN · "+s);try{r.run();}catch(Throwable error){debug("FAIL · "+s+" · "+error.getClass().getSimpleName()+": "+String.valueOf(error.getMessage()));}});return b;}private Button nav(String s,Runnable r){Button b=button(s,r);b.setTextSize(9);b.setTextColor(0xff01ff1f);b.setLayoutParams(new LinearLayout.LayoutParams(0,dp(50),1));return b;}private void debug(String message){post(()->{if(debug!=null)debug.setText("DEBUG · "+new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+" · "+message);});}
  private void setup(){io.execute(()->{try{File bash=new File(host.privateDirectory(),"debian/rootfs/usr/bin/bash");if(bash.isFile()){if(!launchAttempted)launch();return;}JSONObject state=new JSONObject(host.taskStatus());if(!state.optBoolean("busy"))host.startTask(new JSONObject().put("action","shellSetup").toString());}catch(Exception e){show("Setup failed: "+e.getMessage());debug("FAIL · setup · "+e);}});}private void startShell(){io.execute(()->{try{launchAttempted=false;launch();}catch(Exception e){show("Launch failed: "+e.getMessage());debug("FAIL · launch · "+e);}});}
  private final Runnable poll=this::pollNow;private void pollNow(){if(closed)return;try{JSONObject state=new JSONObject(host.taskStatus());show(state.optString("phase")+(state.optBoolean("busy")?" · "+state.optInt("percent")+"%":"")+(state.optString("log").isBlank()?"":"\n"+state.optString("log")));if(!state.optBoolean("busy")&&!launchAttempted&&new File(host.privateDirectory(),"debian/rootfs/usr/bin/bash").isFile()&&process==null)io.execute(()->{try{launch();}catch(Exception e){show("Launch failed: "+e.getMessage());debug("FAIL · auto launch · "+e);}});}catch(Exception error){debug("FAIL · status poll · "+error);}handler.postDelayed(poll,1000);}
  private synchronized void launch()throws Exception{if(process!=null)return;launchAttempted=true;File proot=new File(activity.getApplicationInfo().nativeLibraryDir,"libproot.so"),fs=new File(host.privateDirectory(),"debian/rootfs");if(!proot.canExecute())throw new IOException("Executable PRoot is missing from oTraiL");List<String> c=new ArrayList<>(Arrays.asList(proot.getPath(),"--kill-on-exit","--link2symlink","-0","-r",fs.getCanonicalPath(),"-b","/dev","-b","/proc","-b","/sys"));bind(c,new File("/system"),"/system");bind(c,new File("/vendor"),"/vendor");bind(c,new File("/apex"),"/apex");bind(c,new File(activity.getApplicationInfo().dataDir),"/app-data");bind(c,host.privateDirectory(),"/shell-data");bind(c,activity.getExternalFilesDir(null),"/external-app");if(Build.VERSION.SDK_INT<30||Environment.isExternalStorageManager())bind(c,Environment.getExternalStorageDirectory(),"/shared-storage");c.add("-w");c.add("/root");c.add("/usr/bin/bash");c.add("--noprofile");c.add("--norc");c.add("-i");ProcessBuilder b=new ProcessBuilder(c).redirectErrorStream(true);b.environment().put("HOME","/root");b.environment().put("SHELL","/usr/bin/bash");b.environment().put("TERM","xterm-256color");b.environment().put("PATH","/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");b.environment().put("PROOT_TMP_DIR",activity.getCacheDir().getPath());process=b.start();input=process.getOutputStream();append("[Debian started]\n");java.lang.Process p=process;io.execute(()->read(p));io.execute(()->waitFor(p));}
  private void bind(List<String> c,File f,String guest)throws IOException{if(f==null||!f.exists())return;c.add("-b");c.add(f.getCanonicalPath()+":"+guest);}private void read(java.lang.Process p){try(InputStream in=p.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))>=0)append(new String(b,0,n,StandardCharsets.UTF_8));}catch(Exception e){append("\n[output error: "+e+"]\n");debug("FAIL · shell output · "+e);}}private void waitFor(java.lang.Process p){try{int code=p.waitFor();synchronized(this){if(process==p){process=null;input=null;}}append("\n[Shell exited "+code+(code==159?" · Android blocked a syscall; tap START after reviewing output":"")+"]\n");if(code!=0)debug("FAIL · shell exit code "+code);}catch(InterruptedException e){Thread.currentThread().interrupt();debug("FAIL · shell wait interrupted");}}
  private void send(String text){OutputStream out=input;if(out==null){show("Shell is not running");debug("FAIL · send · shell is not running");return;}io.execute(()->{try{out.write(text.getBytes(StandardCharsets.UTF_8));out.flush();post(()->command.setText(""));}catch(Exception e){show(e.getMessage());debug("FAIL · send · "+e);}});}private void exit(){if(input!=null)send("exit\n");else if(activity!=null)activity.finish();}private void append(String s){post(()->{terminal.append(s.replaceAll("\\u001B\\[[0-?]*[ -/]*[@-~]",""));if(terminalScroll!=null)terminalScroll.post(()->terminalScroll.fullScroll(View.FOCUS_DOWN));});}private void show(String s){post(()->status.setText(s));}private void post(Runnable action){Activity a=activity;if(a!=null&&!closed)a.runOnUiThread(()->{if(!closed&&!a.isDestroyed())action.run();});}private void storage(){if(Build.VERSION.SDK_INT>=30)activity.startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+activity.getPackageName())));}
  private void scpSync(){try{File config=new File(activity.getFilesDir(),"modules/data/mod1/scp.json");JSONObject s=StudioFiles.json(config);String remote=s.getString("user")+"@"+s.getString("host")+":"+s.getString("path"),destination="/app-data/files/modules/data/mod1/projects/scp-workspace";send("mkdir -p "+quote(destination)+" && scp -r "+quote(remote)+"/. "+quote(destination)+"/ && printf '%s' '{\"path\":\"/data/data/"+activity.getPackageName()+"/files/modules/data/mod1/projects/scp-workspace\"}' > /app-data/files/modules/data/mod1/project.json\n");}catch(Exception e){show("Configure SCP in GOD first: "+e.getMessage());debug("FAIL · SCP · "+e);}}private String quote(String s){return "'"+s.replace("'","'\\''")+"'";}
  public void task(File pkg,File data,String request,Progress progress)throws Exception{StudioTasks.run(pkg,data,request,progress);}public void close(){closed=true;handler.removeCallbacks(poll);java.lang.Process p=process;if(p!=null)p.destroy();io.shutdownNow();activity=null;host=null;}
}
